// Normalizar datos del lead para Evolution API
const lead = $input.first().json.body || $input.first().json;

const nombre = (lead.nombre || 'hola').trim();
const whatsappClean = (lead.whatsapp || '').replace(/\D/g, '');
const numberFormatted = whatsappClean.startsWith('52') ? whatsappClean : '52' + whatsappClean;
const nombreNegocio = lead.nombreNegocio || '';
const downloadUrl = lead.downloadUrl || lead.personalDownloadUrl || 'https://www.idealy.com.mx/pagina-express';
const utm = lead.utm || {};

// Mensaje M1 (Entrega de guia segun reporte de conversion)
const textoMensaje = `Hola ${nombre} 👋 Te escribimos de Idealy porque pediste la guía "10 mensajes listos para vender por WhatsApp" en nuestra página. Aquí la tienes: ${downloadUrl}\n\nUna pregunta rápida para mandarte ejemplos de tu giro: ¿ya tienes página web? Responde 1 (sí tengo) o 2 (sería la primera).`;

return {
  nombre,
  whatsappClean,
  numberFormatted,
  nombreNegocio,
  downloadUrl,
  utm_source: utm.source || 'Directo',
  utm_medium: utm.medium || '-',
  utm_campaign: utm.campaign || '-',
  gclid: utm.gclid || '-',
  textoMensaje,
  fechaRegistro: new Date().toISOString()
};
